\label{main-result}
Let $u \in \mathcal{K}_{\psi, \Psi}(\Omega)$ be a solution to the obstacle problem \eqref{obst-def0}, under the assumptions \eqref{HpCp}-\eqref{gtx}. 
If $\psi \in W^{2, \infty}_{\rm loc}(\Omega)$, then $u \in W^{1, \infty}_{\textnormal{loc}}(\Omega)$ and the following estimate 
\begin{equation}
\label{a-priori}
\|(1+|Du|^2)^{\frac{1}{2}}\|_{L^{\infty}(B_{\rho})} \le \, \frac{C}{(R-\rho)^{\beta}} \, \left ( \int_{B_{R}} (1 + |Du|^2)^{\frac{p}{2}} \, dx \right )^{\frac{1}{p}} 
\end{equation}
holds for every $0 < \rho < R$ and with positive constants $C$ and $\beta$ depending on $n, p, \lambda, \Lambda, R, \rho$ and the local bounds for $\|D \psi\|_{W^{1, \infty}}$.

\label{app teorema}
Let $f$ satisfy the growth conditions \eqref{HpCp}, \eqref{HpCq}, \eqref{gtx}, and let $f(x, \xi)$ be a convex $C^2$ function in its second argument. Then the sequence $f^{\ell k}: \Omega \times \mathbb{R}^n \rightarrow [0, + \infty)$ defined in \eqref{defdifellk}, convex in the last variable is such that $ f^{\ell k} \to f $ pointwise as $ (\ell, k) \to + \infty $ for a.e. $x \in \Omega$ and for all $\xi \in \mathbb{R}^n$. Moreover, $f^{\ell k} \to f $ uniformly in $ \Omega_0 \times K $ for every $\Omega_0 \subset \subset \Omega$ and $K$ compact set of $\mathbb{R}^n$. Moreover:
\begin{itemize}
  \item There exist constants $M_1, M_2 >0 $, independent of $k,\ell$ such that 
  \begin{equation}\label{crescita p approssimate}
M_1(1+|\xi|^2)^{\frac{p}{2}} \le f^{\ell k}(x, \xi) \le M_2 (1 + |\xi|^2)^{\frac{p}{2}} \qquad \textnormal{for a.e. $x \in \Omega$, for all $\xi \in \mathbb{R}^n$},
\end{equation}

  \item there exist constants $\lambda_1, \Lambda_1>0$ such that for all $(x, \xi) \in \Omega \times \mathbb{R}^n$ and $\mu \in \mathbb{R}^n $
  \begin{equation}
  \lambda_1 \, (1 + |\xi|^2)^{\frac{p-2}{2}} |\mu|^2  \le \sum_{i,j} f^{\ell k}_{\xi_i \xi_j}(x, \xi) \mu_i \mu_j ,
  \end{equation}
  and 
  \begin{equation}
  |f^{\ell k}_{\xi_i \xi_j}(x, \xi)| \le  \Lambda_1 \, (1 +|\xi|^2)^{\frac{p-2}{2}}.
  \end{equation}

  \item There exists a constant $\Lambda_2>0$ such that for all $(x, \xi) \in \Omega \times \mathbb{R}^n$ 
  \begin{equation}
      |f^{\ell k}_{\xi x}(x, \xi)| \le  \Lambda_2  (1 +|\xi|^{2})^{\frac{p-1}{2}}. 
  \end{equation}
\end{itemize}
